SELECT * FROM (SELECT e.event_id,'M:'||s.movement_id case_id,e.activity,e.timestamp FROM (SELECT 'M:'||movement_id event_id,'Goods Received' activity,occurred_at timestamp,movement_id source_key FROM goods_movement WHERE occurred_at IS NOT NULL AND (movement_code='I')) e JOIN goods_movement s ON s.movement_id=e.source_key WHERE s.movement_id IS NOT NULL UNION ALL SELECT e.event_id,'M:'||s.movement_id case_id,e.activity,e.timestamp FROM (SELECT 'M:'||movement_id event_id,'Goods Dispatched' activity,occurred_at timestamp,movement_id source_key FROM goods_movement WHERE occurred_at IS NOT NULL AND (movement_code='O')) e JOIN goods_movement s ON s.movement_id=e.source_key WHERE s.movement_id IS NOT NULL) ORDER BY case_id,timestamp,event_id;
